import { useInView } from "./helpers";
import { useState, useEffect } from "react";

export default function ReferralRingSection() {
  const [leftRef, leftVisible] = useInView(0.2);
  const [rightRef, rightVisible] = useInView(0.2);
  const [tlRef, tlVisible] = useInView(0.15);
  const [savingsRef, savingsVisible] = useInView(0.2);
  const [isMobile, setIsMobile] = useState(false);

  useEffect(() => {
    const check = () => setIsMobile(window.innerWidth < 1024);
    check();
    window.addEventListener("resize", check);
    return () => window.removeEventListener("resize", check);
  }, []);

  const TIMELINE_EVENTS = [
    {
      label: "Week 0",
      pos: "above",
      desc: null,
      subDesc: "3 agents profiles flagged for tampering at the time of onboarding.",
    },
    {
      label: "Week 2, Day 1",
      pos: "below",
      desc: "2 weeks and 104 tampered documents later, we noticed something was off.",
      subDesc: null,
    },
    {
      label: "Week 2, Day 2",
      pos: "above",
      desc: null,
      subDesc: "Upon digging deeper, we noticed a pattern with all the profiles referred by Vishal.\n• Every profile had a tampered ID\n• Every ID had the same PIN code\n• Every single profile came through Vishal's reference.",
    },
    {
      label: "Week 2, Day 3",
      pos: "below",
      desc: "The entire fake-account ring was flagged, traced and wiped out.",
      subDesc: null,
    },
  ];

  return (
    <section style={{
      padding: isMobile ? "60px 5vw 80px" : "80px 6vw 100px",
      position: "relative",
      backgroundColor: "#000",
      overflow: "hidden"
    }}>
      <style>{`
        /* ── WEB: horizontal timeline ── */
        .timeline-grid {
          display: grid;
          grid-template-columns: repeat(4, 1fr);
          position: relative;
          width: 100%;
        }
        .horizontal-line {
          position: absolute;
          top: 50%;
          left: 0; right: 0;
          height: 2px;
          background: rgba(255,255,255,1);
          transform: translateY(-50%);
          z-index: 1;
        }
        .timeline-item {
          display: flex;
          flex-direction: column;
          align-items: center;
          position: relative;
          z-index: 2;
          min-height: 280px;
          justify-content: center;
        }
        .timeline-content {
          height: 120px;
          display: flex;
          flex-direction: column;
          justify-content: center;
          width: 100%;
          padding: 0 10px;
          text-align: center;
        }
        .dot-container {
          height: 40px;
          display: flex;
          align-items: center;
          justify-content: center;
          position: relative;
          z-index: 3;
        }
        .red-dot {
          width: 16px;
          height: 16px;
          background: #e53e3e;
          border-radius: 50%;
          box-shadow: 0 0 12px rgba(229,62,62,0.6);
          border: 2px solid #e53e3e;
          flex-shrink: 0;
        }

        /* ── MOBILE: vertical timeline ── */
        .timeline-mobile {
          position: relative;
          display: flex;
          flex-direction: column;
          gap: 0;
        }
        .timeline-mobile-line {
          position: absolute;
          left: 50%;
          top: 8px;
          bottom: 8px;
          width: 2px;
          background: rgba(255,255,255,1);
          transform: translateX(-50%);
          z-index: 1;
        }
        .timeline-mobile-row {
          display: grid;
          grid-template-columns: 1fr 32px 1fr;
          align-items: flex-start;
          position: relative;
          z-index: 2;
          min-height: 120px;
          padding: 16px 0;
        }
        .tm-left {
          padding-right: 16px;
          text-align: right;
        }
        .tm-right {
          padding-left: 16px;
          text-align: left;
        }
        .tm-dot-col {
          display: flex;
          align-items: flex-start;
          justify-content: center;
